<script>
document.addEventListener('DOMContentLoaded',function(){const search=document.getElementById('outage-search'),date=document.getElementById('outage-date'),type=document.getElementById('outage-type'),button=document.getElementById('outage-filter'),rows=[...document.querySelectorAll('.outage-row')],empty=document.getElementById('no-results'),count=document.getElementById('count-total');function filter(){const q=(search.value||'').trim().toLowerCase(),d=date.value,t=type.value;let visible=0;rows.forEach(r=>{const okq=!q||r.dataset.search.toLowerCase().includes(q),okd=d==='all'||r.dataset.date===d,okt=t==='all'||r.dataset.type===t,rshow=okq&&okd&&okt;r.style.display=rshow?'':'none';if(rshow)visible++});empty.style.display=visible?'none':'block';count.textContent=visible;button.textContent='نمایش برنامه ⚡';}button.addEventListener('click',filter);search.addEventListener('input',filter);date.addEventListener('change',filter);type.addEventListener('change',filter);});
</script>
